-- GENERATED by tests/bench/edit/make_old_impl.py from commit 971e8cb.  The original implementations, schema mc_old, for A/B timing and equivalence tests.
create schema if not exists mc_old;

create or replace function mc_old.edit_section(p_dim text, p_cx int, p_sy int, p_cz int, p_idx int[], p_names text[], p_canonical boolean default false)
returns int language plpgsql volatile as $$
declare
    d         mc.dimension%rowtype;
    sec_ok    boolean;
    v_bc      int;
    v_fc      int;
    v_pal     text[];
    v_bits    int;
    v_data    bytea;
    v_bpal    text[];
    v_bbits   int;
    v_bdata   bytea;
    nb        int;
    is_global boolean;
    dn        text[];
    cn        text[];
    missing   text;
    nm        text;
    old       text;
    k         int;
    i         int;
    pos       int;
    ent       int;
    li        int;
    pp        int;
    vpl       int;
    msk       bigint;
    vals      int[];
    ids       int[];
    words     bigint[];
    lw        bigint;
    hmb       smallint[];
    hmn       smallint[];
    hws       smallint[];
    hdirty    boolean;
    chunk_ok  boolean;
    hm_changed boolean := false;
    col       int;
    val       int;
    h1        int; h2 int; h3 int;
    changed   int := 0;
    ev_idx    int[] := '{}';
    ev_old    text[] := '{}';
    ev_new    text[] := '{}';
    -- per-call memo of the name-derived flags: a section holds few distinct states, so each is analysed once, not once per edit
    mn        text[] := '{}';   -- names seen
    ma        boolean[] := '{}'; -- is air
    mf        boolean[] := '{}'; -- has fluid
    hn        text[] := '{}';   -- names whose heightmap flags were computed
    hfl       boolean[] := '{}'; -- three flags per name: world_surface, motion_blocking, motion_blocking_no_leaves
    j         int;
    a_new     boolean; f_new boolean; a_old boolean; f_old boolean;
    ofl       boolean[]; nfl boolean[];
begin
    select * into d from mc.dimension where name = p_dim;
    if not found then raise exception 'unknown dimension %', p_dim; end if;
    if p_sy < (d.min_y >> 4) or p_sy >= ((d.min_y + d.height) >> 4) then
        raise exception 'section % is outside dimension % (y % .. %)', p_sy, p_dim, d.min_y, d.min_y + d.height - 1;
    end if;

    -- canonical state names, resolved once per distinct name, in one statement (a bare block name means its default state; unknown names are an error)
    if p_canonical then
        select array_agg(n order by n) into dn from (select distinct n from unnest(p_names) n) q;
        cn := dn;
    else
        select array_agg(q.n order by q.n), array_agg(coalesce(s.name, ds.name) order by q.n), (array_agg(q.n order by q.n) filter (where coalesce(s.name, ds.name) is null))[1]
          into dn, cn, missing
          from (select distinct n from unnest(p_names) n) q
          left join ref.block_state s on s.name = q.n
          left join ref.block b on b.name = q.n
          left join ref.block_state ds on ds.state_id = b.default_state;
        if missing is not null then perform mc.canon_state(missing); end if;       -- raises 'unknown block state ...'
    end if;

    -- the chunk row (and its heightmaps) once; created if this is the first edit in the chunk
    select c.hm_motion_blocking, c.hm_motion_blocking_no_leaves, c.hm_world_surface, c.hm_dirty into hmb, hmn, hws, hdirty
      from mc.chunk c where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz;
    chunk_ok := found;
    if not chunk_ok then insert into mc.chunk (dimension, cx, cz) values (p_dim, p_cx, p_cz) on conflict do nothing; end if;

    select s.block_count, s.fluid_count, s.palette, s.bits, s.data, s.biome_palette, s.biome_bits, s.biome_data
      into v_bc, v_fc, v_pal, v_bits, v_data, v_bpal, v_bbits, v_bdata
      from mc.chunk_section s where s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.sy = p_sy for update;
    sec_ok := found;
    if not sec_ok then
        v_bc := 0; v_fc := 0; v_pal := array['minecraft:air']; v_bits := 0; v_data := ''::bytea; v_bpal := array[d.default_biome]; v_bbits := 0; v_bdata := ''::bytea;
    end if;
    is_global := cardinality(v_pal) = 0;

    -- grow the palette with the names this batch introduces (in order of first use)
    if not is_global then
        foreach nm in array array(select cn[array_position(dn, n)] from unnest(p_names) n) loop
            if array_position(v_pal, nm) is null then v_pal := v_pal || nm; end if;
        end loop;
    end if;
    nb := case when is_global then 16 else mc.block_bits_for(cardinality(v_pal)) end;
    if v_bits = 0 and nb = 0 then return 0; end if;     -- single value, every edit sets that same value

    if v_bits = 0 and nb > 0 then
        -- single value -> palette: every entry is palette index 0 (the old single value), so the packed data starts as zeros; no unpack/repack
        vpl := 64 / nb;
        v_data := decode(repeat('00', ((4096 + vpl - 1) / vpl) * 8), 'hex');
        v_bits := nb;
    end if;

    if nb = v_bits and cardinality(p_idx) <= 48 then
        ---------------------------------------------------------------- few edits, same bit width: overwrite just the affected longs in place (never unpacked)
        vpl := 64 / v_bits;
        msk := (1::bigint << v_bits) - 1;
        for k in 1 .. cardinality(p_idx) loop
            i := p_idx[k];
            nm := cn[array_position(dn, p_names[k])];
            pos := case when is_global then mc.state_id(nm) else array_position(v_pal, nm) - 1 end;
            li := (i / vpl) * 8;                                   -- byte offset of the long holding this entry
            pp := (i % vpl) * v_bits;
            lw := proto.i64_read(v_data, li);
            ent := ((lw >> pp) & msk)::int;
            if ent = pos then continue; end if;
            old := case when is_global then mc.state_name(ent) else v_pal[ent + 1] end;
            v_data := overlay(v_data placing int8send((lw & ~(msk << pp)) | (pos::bigint << pp)) from li + 1 for 8);
            j := array_position(mn, nm);
            if j is null then mn := mn || nm; ma := ma || mc.is_air(nm); mf := mf || mc.has_fluid(nm); j := cardinality(mn); end if;
            a_new := ma[j]; f_new := mf[j];
            j := array_position(mn, old);
            if j is null then mn := mn || old; ma := ma || mc.is_air(old); mf := mf || mc.has_fluid(old); j := cardinality(mn); end if;
            a_old := ma[j]; f_old := mf[j];
            v_bc := v_bc + (case when a_new then 0 else 1 end) - (case when a_old then 0 else 1 end);
            v_fc := v_fc + (case when f_new then 1 else 0 end) - (case when f_old then 1 else 0 end);
            changed := changed + 1;
            ev_idx[changed] := i; ev_old[changed] := old; ev_new[changed] := nm;
        end loop;
    elsif nb = v_bits then
        ---------------------------------------------------------------- many edits, same bit width: unpack the longs once, edit, write back
        vpl := 64 / v_bits;
        msk := (1::bigint << v_bits) - 1;
        words := array(select proto.i64_read(v_data, w * 8) from generate_series(0, (4096 + vpl - 1) / vpl - 1) w order by w);
        for k in 1 .. cardinality(p_idx) loop
            i := p_idx[k];
            nm := cn[array_position(dn, p_names[k])];
            pos := case when is_global then mc.state_id(nm) else array_position(v_pal, nm) - 1 end;
            li := i / vpl + 1;
            pp := (i % vpl) * v_bits;
            ent := ((words[li] >> pp) & msk)::int;
            if ent = pos then continue; end if;
            old := case when is_global then mc.state_name(ent) else v_pal[ent + 1] end;
            words[li] := (words[li] & ~(msk << pp)) | (pos::bigint << pp);
            j := array_position(mn, nm);
            if j is null then mn := mn || nm; ma := ma || mc.is_air(nm); mf := mf || mc.has_fluid(nm); j := cardinality(mn); end if;
            a_new := ma[j]; f_new := mf[j];
            j := array_position(mn, old);
            if j is null then mn := mn || old; ma := ma || mc.is_air(old); mf := mf || mc.has_fluid(old); j := cardinality(mn); end if;
            a_old := ma[j]; f_old := mf[j];
            v_bc := v_bc + (case when a_new then 0 else 1 end) - (case when a_old then 0 else 1 end);
            v_fc := v_fc + (case when f_new then 1 else 0 end) - (case when f_old then 1 else 0 end);
            changed := changed + 1;
            ev_idx[changed] := i; ev_old[changed] := old; ev_new[changed] := nm;
        end loop;
        v_data := (select string_agg(int8send(w), ''::bytea order by o) from unnest(words) with ordinality t(w, o));
    else
        ---------------------------------------------------------------- the bit width changes (palette growth past a width, palette -> global): repack once
        vals := mc.unpack_longs(v_data, v_bits, 4096);
        if not is_global and nb = 16 then
            ids := mc.palette_ids(v_pal);                            -- palette index -> global state id (includes the names added above)
            vals := array(select ids[e + 1] from unnest(vals) with ordinality t(e, o) order by o);
        end if;
        for k in 1 .. cardinality(p_idx) loop
            i := p_idx[k];
            nm := cn[array_position(dn, p_names[k])];
            pos := case when is_global or nb = 16 then mc.state_id(nm) else array_position(v_pal, nm) - 1 end;
            ent := vals[i + 1];
            if ent = pos then continue; end if;
            old := case when is_global or nb = 16 then mc.state_name(ent) else v_pal[ent + 1] end;
            vals[i + 1] := pos;
            j := array_position(mn, nm);
            if j is null then mn := mn || nm; ma := ma || mc.is_air(nm); mf := mf || mc.has_fluid(nm); j := cardinality(mn); end if;
            a_new := ma[j]; f_new := mf[j];
            j := array_position(mn, old);
            if j is null then mn := mn || old; ma := ma || mc.is_air(old); mf := mf || mc.has_fluid(old); j := cardinality(mn); end if;
            a_old := ma[j]; f_old := mf[j];
            v_bc := v_bc + (case when a_new then 0 else 1 end) - (case when a_old then 0 else 1 end);
            v_fc := v_fc + (case when f_new then 1 else 0 end) - (case when f_old then 1 else 0 end);
            changed := changed + 1;
            ev_idx[changed] := i; ev_old[changed] := old; ev_new[changed] := nm;
        end loop;
        v_data := mc.pack_longs(vals, nb);
        v_bits := nb;
        if nb = 16 then v_pal := '{}'; end if;
    end if;

    if changed = 0 then return 0; end if;
    if sec_ok then
        update mc.chunk_section s set block_count = v_bc, fluid_count = v_fc, palette = v_pal, bits = v_bits, data = v_data
         where s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.sy = p_sy;
    else
        insert into mc.chunk_section (dimension, cx, cz, sy, block_count, fluid_count, palette, bits, data, biome_palette, biome_bits, biome_data)
        values (p_dim, p_cx, p_cz, p_sy, v_bc, v_fc, v_pal, v_bits, v_data, v_bpal, v_bbits, v_bdata)
        on conflict (dimension, cx, cz, sy) do update
           set block_count = excluded.block_count, fluid_count = excluded.fluid_count, palette = excluded.palette, bits = excluded.bits, data = excluded.data;
    end if;

    -- Heightmaps are kept exact incrementally (a chunk flagged hm_dirty or without heightmaps is recomputed in full by mc.ensure_chunk_current).
    -- An edit below the top of every column kind it could affect changes nothing (a block placed or removed under the surface), so its flags are not even looked at.
    if hws is not null and not hdirty then
        for k in 1 .. changed loop
            i := ev_idx[k];
            col := (i & 15) + 16 * ((i >> 4) & 15);
            val := p_sy * 16 + (i >> 8) + 1 - d.min_y;
            h1 := hws[col + 1]; h2 := hmb[col + 1]; h3 := hmn[col + 1];
            continue when val < least(h1, h2, h3);
            j := array_position(hn, ev_old[k]);
            if j is null then hn := hn || ev_old[k]; hfl := hfl || mc.heightmap_flags(ev_old[k]); j := cardinality(hn); end if;
            ofl := hfl[(j - 1) * 3 + 1 : (j - 1) * 3 + 3];
            j := array_position(hn, ev_new[k]);
            if j is null then hn := hn || ev_new[k]; hfl := hfl || mc.heightmap_flags(ev_new[k]); j := cardinality(hn); end if;
            nfl := hfl[(j - 1) * 3 + 1 : (j - 1) * 3 + 3];
            hws[col + 1] := mc.hm_step(h1::smallint, val, ofl[1], nfl[1], p_dim, p_cx, p_cz, col, 1, d.min_y);
            hmb[col + 1] := mc.hm_step(h2::smallint, val, ofl[2], nfl[2], p_dim, p_cx, p_cz, col, 2, d.min_y);
            hmn[col + 1] := mc.hm_step(h3::smallint, val, ofl[3], nfl[3], p_dim, p_cx, p_cz, col, 3, d.min_y);
            if hws[col + 1] <> h1 or hmb[col + 1] <> h2 or hmn[col + 1] <> h3 then hm_changed := true; end if;
        end loop;
    end if;
    if hm_changed then
        update mc.chunk c set version = c.version + 1, dirty = true,
                              hm_world_surface = hws, hm_motion_blocking = hmb, hm_motion_blocking_no_leaves = hmn
         where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz;
    else
        update mc.chunk c set version = c.version + 1, dirty = true where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz;
    end if;
    insert into mc.block_event (dimension, x, y, z, old_state, new_state)
    select p_dim, p_cx * 16 + (e.i & 15), p_sy * 16 + (e.i >> 8), p_cz * 16 + ((e.i >> 4) & 15), e.o, e.n
      from unnest(ev_idx, ev_old, ev_new) e(i, o, n);
    return changed;
end $$;

create or replace function mc_old.set_blocks(p_dim text, xs int[], ys int[], zs int[], blocks text[]) returns int language plpgsql volatile as $$
declare
    g     record;
    total int := 0;
begin
    if cardinality(xs) <> cardinality(ys) or cardinality(xs) <> cardinality(zs) or cardinality(xs) <> cardinality(blocks) then
        raise exception 'set_blocks: the four arrays must have the same length';
    end if;
    -- sorted by section so concurrent batches lock in the same order
    for g in
        select t.x >> 4 as cx, t.y >> 4 as sy, t.z >> 4 as cz,
               array_agg(mc.section_idx(t.x, t.y, t.z) order by t.o) as idxs, array_agg(t.b order by t.o) as names
          from unnest(xs, ys, zs, blocks) with ordinality t(x, y, z, b, o)
         group by 1, 2, 3 order by 1, 3, 2
    loop
        total := total + mc_old.edit_section(p_dim, g.cx, g.sy, g.cz, g.idxs, g.names);
    end loop;
    return total;
end $$;

create or replace function mc_old.sky_layer(hm smallint[], base int) returns bytea language sql immutable parallel safe as $$
  select decode(string_agg(lpad(to_hex(
           (case when base + (k >> 7) >= hm[2 * (k & 7) + 16 * ((k >> 3) & 15) + 1] then 15 else 0 end)
         | (case when base + (k >> 7) >= hm[2 * (k & 7) + 16 * ((k >> 3) & 15) + 2] then 240 else 0 end)), 2, '0'), '' order by k), 'hex')
  from generate_series(0, 2047) k $$;

create or replace function mc_old.compute_light(p_dim text, p_cx int, p_cz int, p_sky0_as_data boolean default false) returns void language plpgsql volatile as $$
declare
    d          mc.dimension%rowtype;
    hm         smallint[];
    top        int;
    min_sy     int;
    nsec       int;
    last_layer int;
    lay        int;
    base       int;
    lo         int;
    hi         int;
    arr        bytea;
begin
    select * into d from mc.dimension where name = p_dim;
    if not found then raise exception 'unknown dimension %', p_dim; end if;
    select c.hm_world_surface into hm from mc.chunk c where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz;
    if hm is null then raise exception 'chunk %,% of % has no heightmaps; compute them first', p_cx, p_cz, p_dim; end if;
    min_sy := d.min_y >> 4;
    nsec := d.height / 16;
    select max(s.sy) - min_sy into top from mc.chunk_section s
     where s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.block_count > 0;
    top := coalesce(top, -1);
    last_layer := least(top + 2, nsec + 1);
    select min(x), max(x) into lo, hi from unnest(hm) x;

    delete from mc.chunk_light where dimension = p_dim and cx = p_cx and cz = p_cz;
    for lay in 0 .. last_layer loop
        if lay = 0 then
            insert into mc.chunk_light values (p_dim, p_cx, p_cz, 0,
                case when p_sky0_as_data then 'data' else 'empty' end, case when p_sky0_as_data then decode(repeat('00', 2048), 'hex') end,
                'empty', null);
            continue;
        end if;
        base := (min_sy + lay - 1) * 16 - d.min_y;            -- y of the layer's lowest block, relative to the world bottom
        if base >= hi then
            arr := decode(repeat('ff', 2048), 'hex');
            insert into mc.chunk_light values (p_dim, p_cx, p_cz, lay, 'data', arr, 'empty', null);
        elsif base + 16 <= lo then
            insert into mc.chunk_light values (p_dim, p_cx, p_cz, lay, 'empty', null, 'empty', null);
        else
            insert into mc.chunk_light values (p_dim, p_cx, p_cz, lay, 'data', mc_old.sky_layer(hm, base), 'empty', null);
        end if;
    end loop;
end $$;

create or replace function mc_old.ensure_chunk_current(p_dim text, p_cx int, p_cz int) returns boolean language plpgsql volatile as $$
declare
    c mc.chunk%rowtype;
    h record;
begin
    select * into c from mc.chunk k where k.dimension = p_dim and k.cx = p_cx and k.cz = p_cz for update;
    if not found then return false; end if;
    if not c.dirty and not c.hm_dirty and c.hm_world_surface is not null then return false; end if;
    if c.hm_dirty or c.hm_world_surface is null then
        select * into h from mc.compute_heightmaps(p_dim, p_cx, p_cz);
        update mc.chunk k set hm_motion_blocking = h.motion_blocking, hm_motion_blocking_no_leaves = h.motion_blocking_no_leaves,
                              hm_world_surface = h.world_surface, hm_dirty = false
         where k.dimension = p_dim and k.cx = p_cx and k.cz = p_cz;
    end if;
    perform mc_old.compute_light(p_dim, p_cx, p_cz);
    update mc.chunk k set dirty = false where k.dimension = p_dim and k.cx = p_cx and k.cz = p_cz;
    return true;
end $$;

create or replace function mc_old.section_wire(s mc.chunk_section) returns bytea language sql stable parallel safe as $$
  select proto.i16(s.block_count) || proto.i16(s.fluid_count)
      || mc.container_wire(s.bits, case when cardinality(s.palette) > 0 then mc.palette_ids(s.palette) end, cardinality(s.palette) = 0, s.data)
      || mc.container_wire(s.biome_bits, case when cardinality(s.biome_palette) > 0 then mc.biome_palette_ids(s.biome_palette) end, cardinality(s.biome_palette) = 0, s.biome_data) $$;

create or replace function mc_old.heightmaps_wire(c mc.chunk, p_height int) returns bytea language sql immutable parallel safe as $$
  select proto.varint(3)
      || proto.varint(4) || proto.varint(octet_length(w1) / 8) || w1
      || proto.varint(5) || proto.varint(octet_length(w2) / 8) || w2
      || proto.varint(1) || proto.varint(octet_length(w3) / 8) || w3
  from (select mc.pack_longs(c.hm_motion_blocking, mc.ceillog2(p_height + 1)) w1,
               mc.pack_longs(c.hm_motion_blocking_no_leaves, mc.ceillog2(p_height + 1)) w2,
               mc.pack_longs(c.hm_world_surface, mc.ceillog2(p_height + 1)) w3) q $$;

create or replace function mc_old.light_wire(p_dim text, p_cx int, p_cz int) returns bytea language sql stable parallel safe as $$
  with l as (select * from mc.chunk_light where dimension = p_dim and cx = p_cx and cz = p_cz)
  select mc.bitset_wire(array(select idx::int from l where sky_kind = 'data' order by idx))
      || mc.bitset_wire(array(select idx::int from l where block_kind = 'data' order by idx))
      || mc.bitset_wire(array(select idx::int from l where sky_kind = 'empty' order by idx))
      || mc.bitset_wire(array(select idx::int from l where block_kind = 'empty' order by idx))
      || proto.varint((select count(*)::int from l where sky_kind = 'data'))
      || coalesce((select string_agg(proto.varint(octet_length(sky)) || sky, ''::bytea order by idx) from l where sky_kind = 'data'), '\x')
      || proto.varint((select count(*)::int from l where block_kind = 'data'))
      || coalesce((select string_agg(proto.varint(octet_length(block)) || block, ''::bytea order by idx) from l where block_kind = 'data'), '\x') $$;

create or replace function mc_old.block_entities_wire(p_dim text, p_cx int, p_cz int) returns bytea language sql stable parallel safe as $$
  select proto.varint(count(*)::int)
      || coalesce(string_agg(proto.i8(((e.x & 15) << 4) | (e.z & 15)) || proto.i16(e.y) || proto.varint(r.protocol_id) || e.nbt, ''::bytea order by e.seq), '\x'::bytea)
  from mc.block_entity e
  join ref.registry r on r.registry = 'minecraft:block_entity_type' and r.name = e.type
  where e.dimension = p_dim and e.cx = p_cx and e.cz = p_cz $$;

create or replace function mc_old.chunk_packet_body(p_dim text, p_cx int, p_cz int) returns bytea language plpgsql stable as $$
declare
    d    mc.dimension%rowtype;
    c    mc.chunk%rowtype;
    secs bytea;
    empty bytea;
begin
    select * into d from mc.dimension where name = p_dim;
    select * into c from mc.chunk where dimension = p_dim and cx = p_cx and cz = p_cz;
    if not found then return null; end if;
    if c.hm_world_surface is null then raise exception 'chunk %,% has no heightmaps; call mc.ensure_chunk_current first', p_cx, p_cz; end if;
    empty := mc.empty_section_wire(p_dim);          -- once, not once per missing section
    select string_agg(case when s.sy is null then empty else mc_old.section_wire(s) end, ''::bytea order by g)
      into secs
      from generate_series(d.min_y >> 4, ((d.min_y + d.height) >> 4) - 1) g
      left join mc.chunk_section s on s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.sy = g;
    return proto.i32(p_cx) || proto.i32(p_cz)
        || mc_old.heightmaps_wire(c, d.height)
        || proto.varint(octet_length(secs)) || secs
        || mc_old.block_entities_wire(p_dim, p_cx, p_cz)
        || mc_old.light_wire(p_dim, p_cx, p_cz);
end $$;

create or replace function mc_old.chunk_packet_build(p_dim text, p_cx int, p_cz int) returns bytea language plpgsql volatile as $$
declare
    v   bigint;
    pkt bytea;
begin
    perform mc_old.ensure_chunk_current(p_dim, p_cx, p_cz);
    select c.version into v from mc.chunk c where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz;
    if not found then return null; end if;
    select k.packet into pkt from mc.chunk_cache k where k.dimension = p_dim and k.cx = p_cx and k.cz = p_cz and k.version = v;
    if found then return pkt; end if;
    pkt := proto.frame(mc.chunk_packet_id(), mc_old.chunk_packet_body(p_dim, p_cx, p_cz));
    -- with compression on, the compressed frame is cached with the packet (sql/440): payload = packet id + body = what follows the length VarInt
    insert into mc.chunk_cache (dimension, cx, cz, version, packet, packet_z)
    values (p_dim, p_cx, p_cz, v, pkt, case when mc.compression_enabled() then mc.z_frame(substring(pkt from (select nxt from proto.varint_read(pkt, 0)) + 1)) end)
    on conflict (dimension, cx, cz) do update set version = excluded.version, packet = excluded.packet, packet_z = excluded.packet_z;
    return pkt;
end $$;

create or replace function mc_old.chunk_packet(p_dim text, p_cx int, p_cz int) returns bytea language plpgsql volatile as $$
declare pkt bytea;
begin
    select k.packet into pkt
      from mc.chunk c join mc.chunk_cache k on k.dimension = c.dimension and k.cx = c.cx and k.cz = c.cz and k.version = c.version
     where c.dimension = p_dim and c.cx = p_cx and c.cz = p_cz and not c.dirty and not c.hm_dirty and c.hm_world_surface is not null;
    if found then return pkt; end if;
    return mc_old.chunk_packet_build(p_dim, p_cx, p_cz);
end $$;

